(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ga"] = {"ui":{"skip":"Léim go dtí an t-ábhar","back":"← Ar ais go AI-gile","lang.button":"Teanga: {name}","lang.dialog":"Roghnaigh teanga","lang.search":"Cuardaigh teangacha","lang.none":"Níl teanga ar bith ag teacht leis","lang.notYet":"Níl {name} aistrithe go fóill","theme.aria":"Athraigh idir téama geal agus dorcha","theme.toLight":"Athraigh go téama geal","theme.toDark":"Athraigh go téama dorcha","index.title":"AI-gile: d'fhoireann forbartha AI, ar aon bhord amháin","index.description":"Is bord kanban é AI-gile do fhoirne códaithe AI. Oibríonn siad agus tú i do chodladh; faigheann tú carn gearr amháin rudaí le socrú, le tástáil agus le glacadh leo.","hero.logoAlt":"Deilbhín bhord AI-gile","hero.h1.html":"D'fhoireann forbartha AI, ar aon&nbsp;bhord amháin.","hero.alpha":"🐣 Réamh-alfa dúnta","hero.alphaTitle":"Luath agus neamhchríochnaithe: go raibh maith agat as triail a bhaint as!","hero.lede":"Tógann siad agus tú i do chodladh. Dúiseoidh tú le carn gearr amháin: cúpla ceist, cúpla rud le tástáil, diamant corcra nó dhó. Cliceáil, glac leis, agus ar ais chuig do chaife.","dl.windows":"Aip Windows","dl.browser":"Rith é i do bhrabhsálaí","dl.soon":"Ag teacht go luath","dl.notify":"🔔 Inis dom nuair a osclaíonn sé","dl.notifySmall":"Alfa nó béite","hero.secondary":"Agile, ach ní bhíonn caife seasaimh de dhíth ar an bhfoireann go deo. (Bíonn cruinniú seasaimh acu ar aon nós.)","pitch.h2":"AI-gile i oiread focal agus is mian leat","pitch.lede":"Roghnaigh fad, ó fhocal amháin go 144. Is cur síos dá chuid féin é gach fad, scríofa don mhéid sin. Tarraing an sleamhnán nó úsáid na heochracha saighde.","pitch.rangeLabel":"Fad i bhfocail","pitch.dice":"🎲 leagan eile","pitch.words.one":"{n} fhocal","pitch.words.two":"{n} fhocal","pitch.words.few":"{n} fhocal","pitch.words.many":"{n} bhfocal","pitch.words.other":"{n} focal","pitch.letters.one":"{n} litir","pitch.letters.two":"{n} litir","pitch.letters.few":"{n} litir","pitch.letters.many":"{n} litir","pitch.letters.other":"{n} litir","pitch.chars.one":"{n} charachtar","pitch.chars.two":"{n} charachtar","pitch.chars.few":"{n} charachtar","pitch.chars.many":"{n} gcarachtar","pitch.chars.other":"{n} carachtar","count.line.html.one":"{n} chárta ar an mbord faoi láthair","count.line.html.two":"{n} chárta ar an mbord faoi láthair","count.line.html.few":"{n} chárta ar an mbord faoi láthair","count.line.html.many":"{n} gcárta ar an mbord faoi láthair","count.line.html.other":"{n} cárta ar an mbord faoi láthair","features.aria":"Cad a dhéanann sé","f.pile.h":"Carn amháin duitse","f.pile.html":"Coinníonn <b>Duitse</b> gach rud atá ag fanacht leatsa, thar gach tionscadal: ceisteanna, rudaí le tástáil, tascanna nach féidir ach le duine a dhéanamh. Insíonn do scuaine duit cad atá chugainn agus cén fhad a thógfaidh sé.","f.sleep.h":"Foirne a oibríonn agus tú i do chodladh","f.sleep.p":"Tá ceannaire agus foireann gníomhairí AI ag gach tionscadal. Cuir trácht ar chárta agus dúisíonn an fhoireann, déanann sí an obair, agus tugann sí ar ais é le céimeanna ar féidir le duine tuirseach iad a leanúint.","f.tester.h":"Seiceálann tástálaí AI ar dtús","f.tester.p":"Sula sroicheann aon rud thú, leanann tástálaí na céimeanna i gcóip den aip agus taispeánann sé a bhfaca sé, le seatnóg. Féach go tapa ar na cinn a d'éirigh leo agus glac leo le cliceáil amháin.","f.proof.h":"Cruthúnas, ní geallúintí","f.proof.p":"Taispeánann gach tabhairt thar láimhe cad a athraigh: na comhaid, an diff, na seatnóga. Ní gá gach aip a oscailt le feiceáil an bhfuil sé déanta.","f.chat.h":"Comhrá le do cheannairí","f.chat.p":"Ráille mar Discord: deilbhín amháin an tionscadal, diamaint chorcra do rud a bhfuil tú de dhíth air. Seol smaoineamh chuig ceannaire; déanann sé cártaí agus plean de, le cnaipe ✅ Go.","f.tidy.h":"Coinníonn sé é féin néata","f.tidy.p":"Cuirtear cártaí gaolmhara le chéile, ceartaítear teidil mhearaithe, agus coinníonn seiceáil chomharthaí an cód éadrom. Níos lú rudaí le malartú eatarthu, níos lú le smaoineamh air.","f.private.h":"Ar do ríomhaire féin, duitse","f.private.li1":"Ritheann an bord ar do mheaisín féin agus ní fhreagraíonn sé ach duitse.","f.private.li2":"Tá teachtaireachtaí príobháideacha idir daoine criptithe ó cheann ceann.","f.private.li3":"Gan cuntais, gan lorgairí, gan fianáin.","f.lang.h":"I do theanga féin","f.lang.p":"Os cionn 120 teanga, ón Ollainnis, an Bhreatnais agus an tSeapáinis go dtí cainteanna na bpíoráidí, Yoda agus Klingon, agus aistriú tapa ar ais go Béarla do na focail forbróra.","tl.aria":"Amlíne ón gcéad chomhrá go dtí an treochlár","tl.h2":"Ón gcéad chomhrá go dtí an chéad rud eile","tl.lede":"Dátaí agus amanna fíora, i do chrios ama féin. Tar éis inniu is é an plean atá ann, gan dátaí geallta.","tl.today":"Inniu","tl.planned":"pleanáilte","tl.cards.one":"{n} chárta","tl.cards.two":"{n} chárta","tl.cards.few":"{n} chárta","tl.cards.many":"{n} gcárta","tl.cards.other":"{n} cárta","join.h2":"Bí linn","join.lede":"Tá AI-gile á thógáil ag duine beag amháin agus a lán gníomhairí foighneacha. Tá sé príobháideach faoi láthair, in alfa dúnta le cairde. An mbeadh fonn ort triail a bhaint as nuair a osclaítear é?","join.btn":"Cláraigh spéis","join.small":"Scríobhfaimid chugat, rud ar bith eile ní dhéanfaimid","footer.tag":"AI-gile. Gan lorgairí, gan fianáin, gan caife seasaimh.","footer.licence":"Ceadúnas gnó","footer.status":"Stádas","form.sending":"Á sheoladh…","form.failed":"Níor oibrigh sé sin: bain triail eile as ar ball.","form.offline":"Níorbh fhéidir teacht ar AI-gile: bain triail eile as ar ball.","interest.title":"AI-gile: inis dom nuair a osclaíonn an alfa","interest.description":"Fág do ríomhphost le heolas a fháil nuair a osclaíonn alfa nó béite dúnta AI-gile.","interest.h1":"🔔 Inis dom nuair a osclaíonn sé","interest.lede":"Tá AI-gile i réamh-alfa dúnta. Fág do ríomhphost agus scríobhfaimid uair amháin, nuair a bheidh áit duit.","interest.email":"Do ríomhphost","interest.which":"Cén triail?","interest.alpha":"Alfa dúnta: luath, garbh, a lán athruithe","interest.beta":"Béite: níos seasta, níos déanaí","interest.both":"Ceachtar acu, cibé ceann a thagann ar dtús","interest.submit":"Cuir ar an liosta mé","interest.thanks":"Go raibh maith agat! Tá tú ar an liosta.","licence.title":"AI-gile: ceadúnas gnó","licence.description":"An bhfuil AI-gile in úsáid i do ghnó? Cuir isteach ar cheadúnas gnó saor in aisce.","licence.h1":"📜 Ceadúnas gnó","licence.lede":"An bhfuil AI-gile in úsáid agat ag an obair? Inis dúinn cé thú féin agus cad a dhéanann tú. Má dhéanann sé maitheas, tá an ceadúnas saor in aisce.","licence.company":"Cuideachta","licence.website":"Suíomh gréasáin","licence.what":"Cad a dhéanann tú","licence.how":"Conas a chabhraíonn sé leis an domhan","licence.email":"Ríomhphost","licence.submit":"Cuir isteach","licence.thanks":"Go raibh maith agat! Freagróimid le ríomhphost.","status.title":"Stádas AI-gile","status.h1":"Stádas AI-gile","status.quiet":"Gach rud ciúin","status.checking":"Ag seiceáil…","status.offline":"Níl teacht ar an tseirbhís stádais faoi láthair (ag triail arís)","status.updated":"nuashonraithe {ago}","status.justNow":"díreach anois","status.min":"{n} nóim ó shin","status.hours":"{n} u ó shin","status.days":"{n} lá ó shin","live.h2":"Féach air á thógáil, beo","live.caption":"Tá gach cárta folaithe: feiceann tú cruth na hoibre, ní na focail.","live.watching.one":"beo: {n} ag breathnú","live.watching.other":"beo: {n} ag breathnú","live.offline":"Tá an clár beo ag glacadh sos beag. Fill go luath.","live.cols":"Backlog|Le déanamh|Ar siúl|An fhoireann ag seiceáil|Le test agatsa|Don fhoireann|Déanta","live.last.now":"Bogadh an cárta deireanach díreach anois","live.last.min.one":"Bogadh an cárta deireanach {n} nóiméad ó shin","live.last.min.other":"Bogadh an cárta deireanach {n} nóiméad ó shin","live.last.hour.one":"Bogadh an cárta deireanach {n} uair ó shin","live.last.hour.other":"Bogadh an cárta deireanach {n} uair ó shin","live.last.day.one":"Bogadh an cárta deireanach {n} lá ó shin","live.last.day.other":"Bogadh an cárta deireanach {n} lá ó shin"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Róbónna.","Tarmligthe."]},{"n":2,"texts":["Kanban róbónna.","Gníomhairí, eagraithe.","Smaointe, tógtha."]},{"n":3,"texts":["Kanban do róbónna.","Smaointe ina gcumais.","Kanban gníomhairí saor."]},{"n":5,"texts":["Bord kanban á rith ag gníomhairí.","Scríobhann tú, tógann na gníomhairí.","Saor, áitiúil, tástáilte, beagán áiféiseach."]},{"n":8,"texts":["Bord kanban saor ina n-oibríonn gníomhairí AI.","Scríobh smaoineamh. Tógann gníomhairí é. Glacann tú leis.","Agile do dhuine amháin agus róbónna foighneacha go leor."]},{"n":13,"texts":["Bord kanban ar do ríomhaire inar féidir le gníomhairí AI cártaí a ghlacadh.","Scríobh smaoineamh. Tógann foireann gníomhairí é. Seiceálann tástálaí go n-oibríonn sé.","Saor, gan chuntais, gan lorgairí: bord amháin, roinnt róbónna, agus tusa i gceannas."]},{"n":21,"texts":["Is bord kanban é AI-gile le haghaidh oibre le gníomhairí códaithe AI. Glacann siadsan na cártaí; déanann tusa iad a thástáil agus glacadh leo.","Faigheann gach tionscadal ceannaire agus foireann gníomhairí AI. Cuir trácht ar chárta ar bith agus tosaíonn an fhoireann ag obair.","Bord pearsanta tascanna, saor in aisce, a ritheann ar do ríomhaire féin. Is róbónna na hoibrithe. An té a deir tá, is tusa é."]},{"n":34,"texts":["Cuireann tú smaointe ar bhord. Déanann foireann gníomhairí AI gnéithe oibre díobh, tástálann siad iad, agus tugann siad ar ais chugat iad le céimeanna le triail. Ní chuirtear aon rud i gcrích go dtí go ndeir tusa é.","Is bord kanban baile é AI-gile a thóg Rich le cabhair mhór ó na gníomhairí a bhainistíonn sé anois. Tá sé saor in aisce, ritheann sé ar do ríomhaire, agus roinntear le cairde é, ní dhíoltar é.","Samhlaigh gnáthbhord kanban, le colúin ón mBacklog go Déanta, ach amháin gur gníomhairí AI a ghlacann na cártaí. Tuairiscíonn siad dul chun cinn, cuireann siad ceisteanna nuair a bhíonn siad i bhfostú, agus fanann siad i gcónaí le do cheadú."]},{"n":55,"texts":["Is bord kanban é AI-gile ina bhfuil an fhoireann déanta de ghníomhairí AI. Tá ceannaire ag gach tionscadal a phleanálann an obair agus cúntóirí a thógann í. Nuair a bhíonn gné réidh, baineann tástálaí AI triail aisti agus tógann sé seatnóg, agus ansin tagann sí isteach i do charn. Glac léi, nó cuir trácht agus déanann siad athobair uirthi.","Thosaigh sé mar bhealach ag duine amháin le súil a choinneáil ar a lán seisiún códaithe AI ag an am céanna, agus d'fhás sé ina bhord ceart. Ritheann sé ar do mheaisín, gan cuntas, gan lorgaire. Tá sé saor do chairde agus do dhaoine fiosracha. Tá sé neamhchríochnaithe freisin, mar sin bí ag súil le himill gharbha agus le hiontas anois is arís.","Seo an leagan macánta. Ní mór duit na smaointe a bheith agat fós, agus ní mór duit na torthaí a sheiceáil fós. An rud a dhéanann AI-gile ná gach rud eatarthu: coinníonn sé na cártaí in ord, dúisíonn sé an gníomhaire ceart nuair a chuireann tú trácht, taispeánann sé go díreach cad a athraigh, agus cuireann sé an t-iomlán i gcarn gearr amháin duitse."]},{"n":89,"texts":["Is bord kanban saor é AI-gile a ritheann tú ar do ríomhaire féin. In ionad daoine, tá foireann gníomhairí AI ag gach tionscadal: ceannaire a athraíonn do chuid smaointe ina gcártaí agus ina bplean, agus cúntóirí a ghlacann na cártaí in ord tábhachta. Nuair a bhíonn rud tógtha, leanann tástálaí AI na céimeanna tástála agus taispeánann sé duit a bhfaca sé. Ansin fanann sé i gcarn amháin darb ainm Duitse. Glacann tú leis, nó cuireann tú trácht agus bainfidh an fhoireann triail eile as. Ní shroicheann aon rud Déanta riamh gan tusa.","Roinnt gnéithe nach mbeidh tú ag súil leo b'fhéidir. Coinníonn faire na hoíche an colún Le déanamh lán agus tú i do chodladh, ag roghnú cártaí nach dteastaíonn freagra uait orthu. Taispeánann áireamhán comharthaí cé mhéad a d'úsáid na gníomhairí inniu agus an tseachtain seo, agus deir Mód Gan Chomharthaí leo stopadh den chaitheamh. Is féidir leat teachtaireachtaí a sheoladh chuig cairde, agus tá teachtaireachtaí príobháideacha criptithe ó cheann ceann. Labhraíonn an bord thart ar 120 teanga, an Ollainnis, an Phléimeannais, cainte na bpíoráidí agus Klingon ina measc. Ní chosnaíonn aon cheann de seo pingin.","Tionscadal beag pearsanta é AI-gile, ní cuideachta. Theastaigh ó Rich aire a thabhairt do roinnt tionscadal códaithe AI gan gach aip a oscailt lena seiceáil, mar sin thóg sé féin agus na gníomhairí bord dó, agus d'úsáid siad an bord ansin leis an chuid eile de a thógáil. Tá sé i réamh-alfa dúnta, rud a chiallaíonn go n-oibríonn sé, den chuid is mó, do dornán cairde. Níl leathanach praghsanna ann, níl nuachtlitir ann agus níl plean fáis ann. Má tá sé úsáideach i do thuairim, is féidir leat iarraidh triail a bhaint as nuair a osclaítear beagán níos mó é."]},{"n":144,"texts":["Is bord kanban é AI-gile do dhuine amháin agus a lán gníomhairí AI. Ritheann sé ar do ríomhaire féin agus tá sé go hiomlán saor in aisce. Cuireann tú tionscadail leis, agus faigheann gach tionscadal ceannaire agus foireann bheag. Déanann tú comhrá leis an gceannaire, beagán cosúil le Discord, agus cuireann tú síos ar smaoineamh; déanann an ceannaire cártaí agus plean de, agus fanann sé ansin go mbrúfaidh tú Go. Oibríonn an fhoireann tríd na cártaí in ord tábhachta, ag baint úsáide as líne ordaithe shimplí a rinneadh do mhúnlaí teanga. Sula dtagann aon rud ar ais chugat, leanann tástálaí AI na céimeanna i gcóip den aip agus ceanglaíonn sé seatnóg leis. Tagann an obair chríochnaithe isteach i do charn leis na comhaid athraithe agus an diff. Glacann tú leis, nó fágann tú trácht agus dúisíonn an fhoireann agus bainfidh sí triail eile as. Ní féidir ach leatsa cárta a bhogadh go Déanta.","Lá le AI-gile, thart faoi. Tráthnóna, fágann tú cúpla trácht: tá an cnaipe seo san áit mhícheart, ba chóir an liosta sin a shórtáil, an bhféadfaimis mód dorcha a fháil. Téann tú a luí. Léann na gníomhairí na tráchtanna, déanann siad na hathruithe, tástálann siad iad agus tugann siad ar ais chugat iad. Má thránn Le déanamh, líonann faire na hoíche é ón mbacklog le cártaí nach dteastaíonn freagra uait orthu. Ar maidin tá carn gearr amháin ann: cúpla ceist agus cúpla rud le triail, gach ceann acu le céimeanna ar féidir le duine codlatach iad a leanúint agus seatnóg de é ag obair. Cliceálann tú tríd, glacann tú leis na cinn mhaithe agus seolann tú an chuid eile ar ais. Taispeánann áireamhán comharthaí cad a d'úsáid sé seo ar fad, agus tá Mód Gan Chomharthaí ann do sheachtainí gann. Ansin itheann tú do bhricfeasta, rud nach féidir leis na gníomhairí cabhrú leis fós.","Ar dtús, cad nach ea AI-gile. Ní tosaitheoir é, níl sé le díol, agus níl aon duine ag bailiú do chuid sonraí. Is bord saor é a ritheann ar do ríomhaire, gan chuntais, gan lorgairí agus gan fianáin. Cad is ann dó: áit néata amháin chun gach tionscadal códaithe AI a fheiceáil ag an am céanna, le foireann gníomhairí ag déanamh na gcártaí agus tusa ag déanamh na gcinntí. Cuireann sé cártaí gaolmhara le chéile, ceartaíonn sé teidil mhearaithe, agus coinníonn sé súil ar cé chomh héadrom agus a fhanann an cód. Labhraíonn sé thart ar 120 teanga, ón Ollainnis agus an Phléimeannais go dtí cainteanna na bpíoráidí agus Klingon. Is féidir le cairde teachtaireachtaí a sheoladh dá chéile, go príobháideach agus criptithe. Thóg Rich agus a lán gníomhairí foighneacha é, den chuid is mó ag baint úsáide as féin. Tá sé i réamh-alfa dúnta, mar sin tá sé garbh in áiteanna. Má shamhlaíonn tú go mbeadh spraoi ann, fiafraigh go múinte agus b'fhéidir go mbeidh tú istigh go luath."]}],"quips":{"1":"Focal amháin. Dána. B'fhéidir ró-dhána.","3":"Trí fhocal. Níos macánta cheana ná formhór na leathanach táirge.","8":"Ocht bhfocal. Níos giorra fós ná cruinniú seasaimh.","21":"Pointí scéil atá sna faid, dála an scéil. Ar ndóigh.","55":"Caoga cúig fhocal. Críochnaíodh dhá chárta fad a bhí tú ag léamh sin.","144":"Sin an ceann fada. Níl 233 ann. Tá na gníomhairí imithe a luí."}},"timeline":{"first-idea.name":"An chéad smaoineamh","first-idea.line":"An chéad chomhrá riamh, sula raibh cód ar bith ann.","first-board.name":"An chéad bhord","first-board.line":"Bord a lorgaíonn a thógáil féin: cártaí, colúin, tarraing agus scaoil, tionscadail.","team-roles.name":"Foireann agus róil","team-roles.line":"Próifílí gníomhairí, teimpléid foirne, spásanna agus cé a dhéanann cad.","install.name":"Suiteáil agus eisiúintí","install.line":"Zip is féidir le cara a shuiteáil, féinuasdátú, cainéil agus filleadh ar ais.","usage-saver.name":"Sábhálaí úsáide","usage-saver.line":"Tomhais cad a chosnaíonn rith, coinnigh an cód éadrom, caomhnaigh do theorainn.","friends.name":"Cairde agus comhroinnt","friends.line":"Teachtaireachtaí príobháideacha, athsheachadán mearaithe, cuirí, róil agus tionscadail chomhroinnte.","languages.name":"Teangacha","languages.line":"Gach téacs scáileáin i gcomhad teanga, an Ollainnis agus an Phléimeannais ar dtús.","ai-tester.name":"Tástálaí AI","ai-tester.line":"Seiceálann tástálaí gach tabhairt thar láimhe ar dtús agus taispeánann sé a bhfaca sé.","website.name":"An suíomh gréasáin","website.line":"aigile.lol, an teaser agus an amlíne seo.","streaming.name":"Comhrá agus sruthú","streaming.line":"Discord, Twitch, OBS, mód sruthaitheora, GIFanna agus emoji.","no-ai.name":"Eagrán gan AI","no-ai.line":"Bord do dhaoine a chódaíonn gan AI, agus boird phoiblí.","night-watch.name":"Faire na hoíche","night-watch.line":"Coinníonn fairtheoir agus Scrum Master na foirne ar an tasc agus tú i do chodladh.","p-more.name":"Gach rud eile","p-more.line":"Smaointe níos lú atá fós ag fanacht lena seal.","p-android.name":"Fón agus Android","p-android.line":"Teacht ar do bhord ó fhón, ansin aip dhúchasach Android.","p-release.name":"Alfa agus níos faide","p-release.line":"Alfa dúnta, an suíomh beo, ansin béite.","p-languages.name":"Tuilleadh teangacha","p-languages.line":"Níos mó ná céad teanga, agus mód tumoideachais d'fhoghlaimeoirí.","p-engines.name":"Tuilleadh inneall AI","p-engines.line":"Roghnaigh Claude, Codex nó Gemini do gach gníomhaire.","p-pro.name":"Cleachtas gairmiúil","p-pro.line":"Lipéid riosca, geataí cumasctha, cártaí teagmhais agus ráillí cosanta.","p-self.name":"Aire a thabhairt duit féin","p-self.line":"Mód tuirse, meabhrúcháin féinchúraim agus 4:20.","p-servers.name":"Freastalaithe agus scála","p-servers.line":"Socruithe freastalaí domhanda, róil agus pleanáil don fhás.","p-livestream.name":"Breiseáin sruthaithe","p-livestream.line":"Comhrá Twitch, emoji saincheaptha agus radharc beo poiblí."}};
